    # c2 is gold tier, so the summary applies a discount that the history must carry through.
    big = order(shop, "c2", ("LAMP", 4), ("BOOK", 10)).body["order_id"]
    summary = shop.orders.handle_get(big).body
    assert summary["discount_cents"] > 0
    entry = shop.insights.handle_order_history("c2").body["orders"][0]
    assert entry == {"order_id": big, "status": "placed", "total_cents": summary["total_cents"]}


def test_cancelled_order_total_matches_summary(shop):
    oid = order(shop, "c2", ("LAMP", 4), ("BOOK", 10)).body["order_id"]
    shop.orders.handle_cancel(oid)
    summary = shop.orders.handle_get(oid).body
    entry = shop.insights.handle_order_history("c2").body["orders"][0]
    assert entry == {"order_id": oid, "status": "cancelled", "total_cents": summary["total_cents"]}

